/**
 * Service-account connector authorization for
 * `defineConnection({ cursorAccount: true })` on hosted deployments.
 *
 * Hosted engines authenticate as their deployment's dedicated service
 * account, whose connector OAuth tokens live backend-side. This flow is the
 * dashboard's Authenticate button as a CLI loop: probe the connectors via
 * `CheckHttpMcpStatus` (which mints a complete OAuth `authUrl` per connector
 * needing auth), open each URL for the human to grant, and poll until the
 * backend reports the token stored. Nothing token-shaped ever touches this
 * process — the cursor.com callback stores tokens against the service
 * account. Used by `agent-sdk mcp oauth <connection>` and the post-deploy
 * hook in `cli-deploy.ts`.
 */
import { LOG_PREFIX } from "./distribution.js";
import { openBrowser } from "./mcp-oauth.js";
import { sleep as defaultSleep } from "./sleep.js";
const DEFAULT_POLL_INTERVAL_MS = 3_000;
const DEFAULT_POLL_TIMEOUT_MS = 5 * 60 * 1000;
/** Same default the dashboard uses; MCP_OAUTH_REDIRECT_URI overrides for dev. */
export function mcpOauthRedirectUri() {
    const override = process.env.MCP_OAUTH_REDIRECT_URI;
    if (override !== undefined && override.trim() !== "") {
        return override.trim();
    }
    return "https://www.cursor.com/agents/mcp/oauth/callback";
}
/**
 * Authorize the deployment service account for the connection's connectors.
 * Already-authorized connectors are skipped; the rest get a browser OAuth
 * each (sequentially), polled until the backend stores the token.
 */
export async function authorizeCursorAccountConnectors(args) {
    const { backendClient, teamId, serviceAccountId, connectionName, out, err } = args;
    const open = args.openBrowserImpl ?? openBrowser;
    const sleep = args.sleep ?? defaultSleep;
    const pollIntervalMs = args.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS;
    const pollTimeoutMs = args.pollTimeoutMs ?? DEFAULT_POLL_TIMEOUT_MS;
    const redirectUri = mcpOauthRedirectUri();
    // Team-scoped connectors only: the hosted bridge resolves the SA's team
    // servers, so personal connectors can never apply to a deployment.
    const available = (await backendClient.getAvailableMcpServers({ teamId })).filter((server) => server.isTeamServer);
    const selected = selectConnectors(available, args.servers);
    for (const missing of selected.unmatched) {
        err(`${LOG_PREFIX} Connection "${connectionName}" lists connector ${JSON.stringify(missing)}, but the team has no such connector (dashboard → MCP).\n`);
    }
    if (selected.servers.length === 0) {
        err(`${LOG_PREFIX} No matching team connectors for connection "${connectionName}".\n`);
        return { authorized: [], pending: [], errored: [] };
    }
    const nameById = new Map(selected.servers.map((server) => [server.id, server.name]));
    const statuses = await backendClient.checkHttpMcpStatus({
        serverIds: selected.servers.map((server) => server.id),
        oauthRedirectUri: redirectUri,
        serviceAccountId,
        userInitiated: args.interactive,
    });
    const result = {
        authorized: [],
        pending: [],
        errored: [],
    };
    for (const status of statuses) {
        const name = nameById.get(status.id) ?? `#${status.id}`;
        if (!status.requiresAuth) {
            if (status.error !== undefined && status.error !== "") {
                err(`${LOG_PREFIX} ${name}: ${status.error}\n`);
                result.errored.push({ name, error: status.error });
                continue;
            }
            out(`${LOG_PREFIX} ${name}: already authorized ✓\n`);
            result.authorized.push(name);
            continue;
        }
        const authUrl = status.authUrl ?? "";
        const failure = status.error ?? "";
        // A report-only probe is not a person's sign-in, so the backend may mint no URL for it.
        if (authUrl === "" && (failure !== "" || args.interactive)) {
            const error = failure !== "" ? failure : "no authorization URL was minted";
            err(`${LOG_PREFIX} ${name}: ${error}\n`);
            result.errored.push({ name, error });
            continue;
        }
        if (!args.interactive) {
            result.pending.push(name);
            continue;
        }
        out(`${LOG_PREFIX} ${name}: authorization needed. You'll authorize ${name} as yourself; ` +
            `anyone who can talk to this agent can act with that access.\n` +
            `${LOG_PREFIX} Opening (or open manually):\n  ${authUrl}\n`);
        open(authUrl);
        const authorized = await pollUntilAuthorized({
            backendClient,
            serverId: status.id,
            serviceAccountId,
            redirectUri,
            sleep,
            pollIntervalMs,
            pollTimeoutMs,
        });
        if (authorized) {
            out(`${LOG_PREFIX} ${name}: authorized ✓\n`);
            result.authorized.push(name);
        }
        else {
            err(`${LOG_PREFIX} ${name}: still waiting on authorization; giving up for now.\n`);
            result.pending.push(name);
        }
    }
    return result;
}
function selectConnectors(available, filter) {
    if (filter === undefined || filter.length === 0) {
        return { servers: available, unmatched: [] };
    }
    const servers = [];
    const seen = new Set();
    const unmatched = [];
    for (const name of filter) {
        const wanted = name.trim().toLowerCase();
        const matches = available.filter((server) => server.name.toLowerCase() === wanted || server.serverIdentifier?.toLowerCase() === wanted);
        if (matches.length === 0) {
            unmatched.push(name);
            continue;
        }
        for (const match of matches) {
            if (!seen.has(match.id)) {
                seen.add(match.id);
                servers.push(match);
            }
        }
    }
    return { servers, unmatched };
}
function uniqueConnectorMatch(available, identifier) {
    const wanted = identifier.trim().toLowerCase();
    if (wanted === "") {
        return undefined;
    }
    const byIdentifier = available.filter((server) => server.serverIdentifier?.toLowerCase() === wanted);
    if (byIdentifier.length === 1) {
        return byIdentifier[0];
    }
    if (byIdentifier.length > 1) {
        return undefined;
    }
    const byName = available.filter((server) => server.name.toLowerCase() === wanted);
    if (byName.length === 1) {
        return byName[0];
    }
    return undefined;
}
/**
 * Mint OAuth `authUrl`s for connectors matching `identifiers` (name or
 * `serverIdentifier`). Omit `serviceAccountId` to probe the signed-in user
 * (local `serve` preflight). A status read passes `userInitiated: false`,
 * so a connector that needs authorization can come back without a URL; a
 * sign-in the agent starts passes `undefined`. Connectors without a URL, and
 * every connector when the probe fails, are left out of the map so the
 * caller can point the person elsewhere.
 */
export async function probeConnectorAuthUrls(args) {
    const urls = new Map();
    if (args.identifiers.length === 0) {
        return urls;
    }
    try {
        const available = await args.client.getAvailableMcpServers();
        const matched = [];
        const seen = new Set();
        for (const identifier of args.identifiers) {
            const match = uniqueConnectorMatch(available, identifier);
            if (match === undefined || seen.has(match.id)) {
                continue;
            }
            seen.add(match.id);
            matched.push(match);
        }
        if (matched.length === 0) {
            return urls;
        }
        const statuses = await args.client.checkHttpMcpStatus({
            serverIds: matched.map((server) => server.id),
            oauthRedirectUri: mcpOauthRedirectUri(),
            serviceAccountId: args.serviceAccountId,
            userInitiated: args.userInitiated,
        });
        const statusById = new Map(statuses.map((status) => [status.id, status]));
        for (const identifier of args.identifiers) {
            const match = uniqueConnectorMatch(available, identifier);
            if (match === undefined) {
                continue;
            }
            const authUrl = statusById.get(match.id)?.authUrl?.trim();
            if (authUrl !== undefined && authUrl !== "") {
                urls.set(identifier, authUrl);
            }
        }
        return urls;
    }
    catch {
        return urls;
    }
}
async function pollUntilAuthorized(args) {
    const deadline = Date.now() + args.pollTimeoutMs;
    // Each unauthorized probe is a full backend connect to the provider, so
    // back off while the human works through the OAuth pages.
    let intervalMs = args.pollIntervalMs;
    const maxIntervalMs = Math.max(args.pollIntervalMs, 15_000);
    while (Date.now() < deadline) {
        await args.sleep(intervalMs);
        intervalMs = Math.min(intervalMs * 1.5, maxIntervalMs);
        let statuses;
        try {
            statuses = await args.backendClient.checkHttpMcpStatus({
                serverIds: [args.serverId],
                oauthRedirectUri: args.redirectUri,
                serviceAccountId: args.serviceAccountId,
                userInitiated: false,
            });
        }
        catch {
            // Transient probe errors; keep polling until the deadline.
            continue;
        }
        const status = statuses.find((entry) => entry.id === args.serverId);
        if (status !== undefined && !status.requiresAuth) {
            return true;
        }
    }
    return false;
}
